function smallestSubsequence(s) {
  // Pick the answer one letter at a time: the smallest letter whose first copy still leaves every other needed letter after it.
  let result = '';
  let rest = s;
  while (rest.length > 0) {
    const needed = [...new Set(rest)].sort();
    for (const ch of needed) {
      const suffix = rest.slice(rest.indexOf(ch));
      if (needed.every(other => suffix.includes(other))) {
        result += ch;
        rest = suffix.slice(1).split(ch).join('');
        break;
      }
    }
  }
  return result;
}

