function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const k = size === 'large' ? [3, 8, 15, 26][Math.floor(rand() * 4)] : 1 + Math.floor(rand() * 5);
  const offset = Math.floor(rand() * (27 - k));
  const n = size === 'large' ? 800 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 10);
  return [Array.from({ length: n }, () => letters[offset + Math.floor(rand() * k)]).join('')];
}
